/// <summary>
/// The <c>METVendSiteLeadTimeUpdController</c> class opens the <c>METVendSiteLeadTimeUpd</c> Batch job
/// </summary>
class METVendSiteLeadTimeUpdController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>
    /// Calling the service class
    /// </summary>
    public void new()
    {
        super();

        this.parmClassName(classStr(METVendSiteLeadTimeUpdService));
        this.parmMethodName(methodStr(METVendSiteLeadtimeUpdService, processOperation));
        this.parmDialogCaption("@MET:METLeadTimeUpdVStoIS");
    }

/// <summary>
/// Batch job caption
/// </summary>
/// <returns>Caption</returns>
public ClassDescription caption()
{
    return "@MET:METLeadTimeUpdVStoIS";
}

/// <summary>
/// Controller main method called from action menu item
/// </summary>
/// <param name = "_args">args from output menu item</param>
public static void main(Args _args)
{
    SysOperationController controller = new METVendSiteLeadTimeUpdController();
    controller.startOperation();
}
